insert into order_detail (name, order_id, dish_id, setmeal_id, dish_flavor, number, amount, image)
select concat(#{orderDetail.name},''), cast(#{orderDetail.orderId} as signed), cast(#{orderDetail.dishId} as signed), cast(#{orderDetail.setmealId} as signed), concat(#{orderDetail.dishFlavor},''), cast(#{orderDetail.number} as signed), cast(#{orderDetail.amount} as decimal(10,2)), concat(#{orderDetail.image},'') from orders where id=#{orderDetail.orderId}
and ((#{orderDetail.dishId} is not null and #{orderDetail.setmealId} is null and exists (select 1 from dish where dish.id=#{orderDetail.dishId} and dish.tenant_id=orders.tenant_id)) or (#{orderDetail.setmealId} is not null and #{orderDetail.dishId} is null and exists (select 1 from setmeal where setmeal.id=#{orderDetail.setmealId} and setmeal.tenant_id=orders.tenant_id)))
and exists (select 1 from orders where id=#{check.orderId}
and ((#{check.dishId} is not null and #{check.setmealId} is null and exists (select 1 from dish where dish.id=#{check.dishId} and dish.tenant_id=orders.tenant_id)) or (#{check.setmealId} is not null and #{check.dishId} is null and exists (select 1 from setmeal where setmeal.id=#{check.setmealId} and setmeal.tenant_id=orders.tenant_id))))
